const request = require('supertest');
const app = require('./app');

describe('POST /check', () => {
  it('should evaluate a simple rule expression', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      });

    expect(response.status).toBe(200);
    expect(response.body.result).toBe(true);
  });

  it('should evaluate a rule using context and request', async () => {
    const response = await request(app)
      .post('/check')
      .set('X-Custom-Header', 'test')
      .send({
        rule: 'ctx.user === "alice" && req.headers["x-custom-header"] === "test"',
        context: { user: 'alice' }
      });

    expect(response.status).toBe(200);
    expect(response.body.result).toBe(true);
  });

  it('should return false for non-matching rule', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 50 }
      });

    expect(response.status).toBe(200);
    expect(response.body.result).toBe(false);
  });

  it('should handle syntax errors gracefully', async () => {
    const response = await request(app)
      .post('/check')
      .send({
        rule: 'ctx.amount >',
        context: { amount: 150 }
      });

    expect(response.status).toBe(400);
    expect(response.body).toHaveProperty('error');
  });
});

